def normalize_vendor_onboarding_data(apps, _schema_editor):
    vendor_model = apps.get_model("gsshop_purchase", "VendorProfile")
    legal_document_model = apps.get_model("gsshop_purchase", "VendorLegalDocument")
    prequalification_model = apps.get_model("gsshop_purchase", "VendorPrequalification")
    document_review_model = apps.get_model("gsshop_purchase", "VendorDocumentReview")

    vendor_model.objects.filter(status="active").update(status="confirmed")
    vendor_model.objects.filter(status="suspended").update(status="draft")

    legal_document_model.objects.filter(mandatory=True).update(
        requirement_type="required",
        is_blocking=True,
    )
    legal_document_model.objects.filter(mandatory=False).update(
        requirement_type="optional",
        is_blocking=False,
    )
    legal_document_model.objects.filter(status="valid").update(review_status="approved")
    legal_document_model.objects.filter(status="rejected").update(review_status="rejected")

    prequalification_model.objects.filter(status="under_review").update(status="review")
    vendor_company = vendor_model.objects.filter(pk=OuterRef("vendor_id")).values("company_id")[:1]
    prequalification_model.objects.filter(company__isnull=True).update(
        company_id=Subquery(vendor_company)
    )
    document_review_model.objects.filter(status="accepted").update(status="approved")


